import{_ as s,o as a,c as e,az as t}from"./chunks/framework.CoCPy0Mb.js";const g=JSON.parse('{"title":"Models & Providers","description":"","frontmatter":{},"headers":[],"relativePath":"guide/models-and-providers.md","filePath":"guide/models-and-providers.md"}'),l={name:"guide/models-and-providers.md"};function n(h,i,r,o,p,d){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="models-providers" tabindex="-1">Models &amp; Providers <a class="header-anchor" href="#models-providers" aria-label="Permalink to “Models &amp; Providers”">​</a></h1><p>ImagenHub aggregates multiple AI image generation models across different providers. You choose a model; ImagenHub handles the provider routing.</p><h2 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to “Models”">​</a></h2><p>A <strong>model</strong> represents an AI image generation model (e.g., DALL-E 3, Flux Dev, Stable Diffusion XL). Each model defines:</p><ul><li><strong>Input schema</strong> — JSON schema describing accepted parameters (prompt, size, style, etc.)</li><li><strong>Providers</strong> — Which providers offer this model and at what cost</li></ul><h3 id="list-all-models" tabindex="-1">List all models <a class="header-anchor" href="#list-all-models" aria-label="Permalink to “List all models”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/models</span></span></code></pre></div><p>No authentication required. Returns all visible models with their input schemas and provider options.</p><h3 id="get-a-specific-model" tabindex="-1">Get a specific model <a class="header-anchor" href="#get-a-specific-model" aria-label="Permalink to “Get a specific model”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/models/1</span></span></code></pre></div><p>Returns full details including the <code>input</code> JSON schema and all available <code>providers</code> with per-request cost.</p><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to “Providers”">​</a></h2><p>A <strong>provider</strong> is a third-party AI service that hosts models (e.g., OpenAI, Fal.ai, Replicate). The same model may be available from multiple providers at different price points.</p><h3 id="list-all-providers" tabindex="-1">List all providers <a class="header-anchor" href="#list-all-providers" aria-label="Permalink to “List all providers”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/providers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer sk_live_YOUR_KEY&quot;</span></span></code></pre></div><h3 id="model-provider-combinations" tabindex="-1">Model-provider combinations <a class="header-anchor" href="#model-provider-combinations" aria-label="Permalink to “Model-provider combinations”">​</a></h3><p>To see all model-provider combinations with cost and endpoint details:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/model-providers</span></span></code></pre></div><p>Filter by model or provider:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># All providers for model 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/model-providers?model_id=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># All models from provider 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.imagenhub.ai/api/model-providers?provider_id=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span></code></pre></div><h2 id="how-routing-works" tabindex="-1">How routing works <a class="header-anchor" href="#how-routing-works" aria-label="Permalink to “How routing works”">​</a></h2><p>When you submit a request to <code>/process</code>, ImagenHub:</p><ol><li>Looks up available providers for the requested model</li><li>Checks if you have a <a href="/guide/byok">BYOK key</a> for any of those providers</li><li>Routes to the best available provider</li><li>Transforms your input to match the provider&#39;s format</li><li>Returns the result in ImagenHub&#39;s unified format</li></ol><p>You can also request a specific provider by passing a <code>provider</code> field in the request body.</p><h2 id="input-format" tabindex="-1">Input format <a class="header-anchor" href="#input-format" aria-label="Permalink to “Input format”">​</a></h2><p>Each model defines its own input schema. The common pattern is typed key-value pairs:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prompt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A sunset over mountains&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1024x1024&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;style&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;natural&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Check the model&#39;s <code>input</code> field for the full schema of accepted parameters.</p>`,28)])])}const c=s(l,[["render",n]]);export{g as __pageData,c as default};
